#!/bin/bash
# Builds the procedural dinosaurs (tools/blender/dino_build.py) and converts
# them with tools/dino_convert.py into .dino files and textures in DINO_OUT,
# then checks their clips (tools/proc_dino_check.py). Run from the repository
# root. Everything is generated by code in the repository: nothing is
# downloaded and no other model is read.
#   ocean/cretaceous/tools/build_proc_dinos.sh [raptor|stego|trex|pachy|sauropelta|galli ...]
# Environment: BLENDER (default: blender on PATH), DINO_OUT (default
# ocean/cretaceous/assets/dinos_proc, gitignored), DINO_TMP (the
# intermediate glTFs, default build/cret_proc_dinos), DINO_RENDER (a folder:
# also write the review renders there), DINO_SAMPLES (Cycles samples, 64).
# The game loads the result with CRET_DINO_DIR=$DINO_OUT (docs/proc_dino.md).
set -e
BLENDER=${BLENDER:-blender}
OUT=${DINO_OUT:-ocean/cretaceous/assets/dinos_proc}
TMP=${DINO_TMP:-build/cret_proc_dinos}
PY=${PYTHON:-python3}
HERE=$(cd "$(dirname "$0")" && pwd)
SPECIES=("$@"); [ ${#SPECIES[@]} -eq 0 ] && SPECIES=(raptor stego trex pachy sauropelta galli)
mkdir -p "$OUT" "$TMP"
for sp in "${SPECIES[@]}"; do
    case "$sp" in raptor|stego|trex|pachy|sauropelta|galli) ;; *) echo "unknown species $sp" >&2; exit 1;; esac
    render=(); [ -n "$DINO_RENDER" ] && render=(--render "$DINO_RENDER" --samples "${DINO_SAMPLES:-64}")
    "$BLENDER" -b --factory-startup --disable-autoexec --python-exit-code 1 -P "$HERE/blender/dino_build.py" -- \
        "$sp" "$TMP/$sp.glb" "${render[@]}" 2>&1 | grep -E "^dino_build|Error|Traceback" || true
    [ -f "$TMP/$sp.glb.json" ] && [ "$TMP/$sp.glb.json" -nt "$HERE/blender/dino_build.py" ] || { echo "build failed for $sp" >&2; exit 1; }
    # The converter takes the length and the gait speeds the generator used (the sim's).
    read -r length speeds < <("$PY" -c 'import json,sys; j=json.load(open(sys.argv[1])); s=j["speeds"]; print(j["length"], "walk=%g,trot=%g,run=%g" % (s["walk"], s["trot"], s["run"]))' "$TMP/$sp.glb.json")
    rm -f "$OUT/$sp.dino"
    "$BLENDER" -b --factory-startup --disable-autoexec --python-exit-code 1 --python "$HERE/dino_convert.py" -- \
        "$TMP/$sp.glb" "$sp" "$OUT" --length "$length" --tex 1024 --speed "$speeds" --map idle=idle 2>&1 \
        | grep -E "^dino: (wrote|LOD|material)|Error|Traceback" || true
    [ -f "$OUT/$sp.dino" ] || { echo "conversion failed for $sp" >&2; exit 1; }
done
"$PY" "$HERE/proc_dino_check.py" "$OUT" "${SPECIES[@]}" --md "$OUT/check.md" --json "$OUT/check.json"
